<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use App\Services\CcsAdministration;
class CcsClaimController extends Controller {
 private function warranty(int $id){$w=DB::table('warranties as w')->join('repair_jobs as j','j.id','=','w.repair_job_id')->join('vehicles as v','v.id','=','j.vehicle_id')->join('customers as c','c.id','=','v.customer_id')->where('w.id',$id)->whereNull('j.deleted_at')->whereNull('v.deleted_at')->whereNull('c.deleted_at')->select('w.*','j.vehicle_id','v.customer_id','v.registration_number','c.name as customer_name','j.job_category')->first();abort_unless($w,404);return $w;}
 public function index(Request $request){$request->validate(['q'=>'nullable|string|max:150','warranty_id'=>'nullable|integer','status'=>'nullable|in:pending,approved,rejected,completed']);$q=trim((string)$request->input('q',''));$selected=$request->filled('warranty_id')?$this->warranty((int)$request->warranty_id):null;
  $claims=DB::table('warranty_claims as cl')->join('warranties as w','w.id','=','cl.warranty_id')->join('repair_jobs as j','j.id','=','w.repair_job_id')->join('vehicles as v','v.id','=','j.vehicle_id')->join('customers as c','c.id','=','v.customer_id')->whereNull('c.deleted_at')->whereNull('v.deleted_at')->whereNull('j.deleted_at')->when($request->filled('status'),fn($x)=>$x->where('cl.status',$request->status))->when($q!=='',fn($x)=>$x->where(fn($y)=>$y->where('c.name','like','%'.$q.'%')->orWhere('v.registration_number','like','%'.$q.'%')->orWhere('w.terms_snapshot','like','%'.$q.'%')->orWhere('c.phone','like','%'.$q.'%')))->select('cl.*','w.terms_snapshot','w.expires_on','v.registration_number','c.name as customer_name')->orderByDesc('cl.id')->paginate(15)->withQueryString();return view('ccs.claims',compact('claims','selected','q'));}
 public function store(Request $request){$data=$request->validate(['warranty_id'=>'required|integer','received_on'=>'required|date_format:Y-m-d|before_or_equal:today','problem'=>'required|string|max:5000']);$w=$this->warranty((int)$data['warranty_id']);$snapshot=json_decode($w->terms_snapshot,true)??[];if(($snapshot['provisional']??true)!==false||($snapshot['coverage_kind']??'')==='no_warranty')throw ValidationException::withMessages(['warranty_id'=>'Choose an issued warranty card with coverage.']);
  DB::transaction(function()use($request,$data,$w){DB::table('warranties')->where('id',$w->id)->lockForUpdate()->first();if(DB::table('warranty_claims')->where('warranty_id',$w->id)->whereIn('status',['pending','approved'])->exists())throw ValidationException::withMessages(['warranty_id'=>'This card already has an open claim. Update the existing claim.']);$id=DB::table('warranty_claims')->insertGetId($data+['created_by'=>$request->user()->id,'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);app(CcsAdministration::class)->audit($request->user()->id,'warranty_claim_created','warranty_claim',$id);});return redirect()->route('ccs.claims.index')->with('success','Claim recorded. Coverage requires owner review.');}
 public function update(Request $request,int $id){$data=$request->validate(['findings'=>'required|string|max:5000']);DB::transaction(function()use($id,$data,$request){$claim=DB::table('warranty_claims')->where('id',$id)->lockForUpdate()->first();abort_unless($claim,404);$this->warranty($claim->warranty_id);abort_unless($claim->status==='pending',409,'Only pending findings can be changed.');DB::table('warranty_claims')->where('id',$id)->update($data+['updated_at'=>now()]);app(CcsAdministration::class)->audit($request->user()->id,'warranty_claim_findings_saved','warranty_claim',$id);});return back()->with('success','Findings saved.');}
 public function decision(Request $request,int $id){$data=$request->validate(['status'=>'required|in:approved,rejected,completed','decision_notes'=>'required|string|max:5000','confirmation'=>'required|accepted']);DB::transaction(function()use($request,$id,$data){$c=DB::table('warranty_claims')->where('id',$id)->lockForUpdate()->first();abort_unless($c,404);$this->warranty($c->warranty_id);if(!(($c->status==='pending'&&in_array($data['status'],['approved','rejected'],true))||($c->status==='approved'&&$data['status']==='completed')))throw ValidationException::withMessages(['status'=>'This claim transition is not allowed.']);if(in_array($data['status'],['approved','rejected'],true)&&!trim((string)$c->findings))throw ValidationException::withMessages(['status'=>'Record technician findings before deciding.']);DB::table('warranty_claims')->where('id',$id)->update(['status'=>$data['status'],'decision_notes'=>$data['status']==='completed'?trim((string)$c->decision_notes)."\n\nCompleted: ".$data['decision_notes']:$data['decision_notes'],'decided_by'=>$request->user()->id,'decided_at'=>now(),'completed_at'=>$data['status']==='completed'?now():null,'updated_at'=>now()]);app(CcsAdministration::class)->audit($request->user()->id,'warranty_claim_'.$data['status'],'warranty_claim',$id);});return back()->with('success','Claim status saved.');}
 public function job(Request $request,int $id){$jobId=DB::transaction(function()use($request,$id){$c=DB::table('warranty_claims')->where('id',$id)->lockForUpdate()->first();abort_unless($c,404);$w=$this->warranty($c->warranty_id);abort_unless($c->status==='approved',409,'Approve the claim before opening its repair job.');if($c->repair_job_id)return $c->repair_job_id;$job=DB::table('repair_jobs')->insertGetId(['vehicle_id'=>$w->vehicle_id,'job_number'=>'PENDING-'.Str::uuid(),'job_category'=>$w->job_category,'service_type'=>'Warranty claim inspection / repair','complaint'=>$c->problem,'status'=>'vehicle_received','received_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('repair_jobs')->where('id',$job)->update(['job_number'=>sprintf('CCS-J%06d',$job)]);DB::table('warranty_claims')->where('id',$id)->update(['repair_job_id'=>$job,'updated_at'=>now()]);app(CcsAdministration::class)->audit($request->user()->id,'warranty_claim_job_created','warranty_claim',$id,['repair_job_id'=>$job]);return $job;});return redirect()->route('ccs.jobs.card',$jobId);}
}
